(function() {
    'use strict';

    class AuditTrailAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'AuditTrail: Audit Risk Assessment Lab';
            this.version = '1.1.0';
            this.PHASE_NAMES_EN = ['Risk Assessment', 'Controls Testing', 'Substantive Testing', 'Findings and Opinion'];
            this.PHASE_NAMES_ES = ['Evaluaci\u00f3n de Riesgos', 'Pruebas de Controles', 'Pruebas Sustantivas', 'Hallazgos y Opini\u00f3n'];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    redFlagsFound: 0,
                    falsePositives: 0,
                    auditQuality: '--',
                    phaseScores: [],
                    phaseLabels: [],
                    currentPhaseName: 'Risk Assessment',
                    materialitySet: 0,
                    riskProfile: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    materiality: 150000,
                    riskRevenue: 'medium',
                    riskInventory: 'medium',
                    riskReceivables: 'medium',
                    controlRisk: 'medium',
                    selectedControls: [],
                    controlEffectiveness: 'partially_effective',
                    revenueTest: 'vouching',
                    inventoryTest: 'observation',
                    receivablesTest: 'confirmation',
                    sampleSize: 'medium',
                    identifiedFlags: [],
                    auditOpinion: 'qualified'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var phase = state.currentPeriod || 1;
            this._updateBriefing(state);

            if (phase === 1) {
                var matInput = document.getElementById('materialityInput');
                if (matInput) decisions.materiality = parseInt(matInput.value);
                var rr = document.getElementById('riskRevenue');
                if (rr) decisions.riskRevenue = rr.value;
                var ri = document.getElementById('riskInventory');
                if (ri) decisions.riskInventory = ri.value;
                var rrc = document.getElementById('riskReceivables');
                if (rrc) decisions.riskReceivables = rrc.value;
                var cr = document.getElementById('controlRisk');
                if (cr) decisions.controlRisk = cr.value;

                if (!decisions.materiality || decisions.materiality < 50000 || decisions.materiality > 500000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('materiality_warning'), 'warning'
                    );
                    return false;
                }
            } else if (phase === 2) {
                var selected = [];
                for (var i = 1; i <= 8; i++) {
                    var cb = document.getElementById('ctrl' + i);
                    if (cb && cb.checked) selected.push('ctrl' + i);
                }
                decisions.selectedControls = selected;
                var ce = document.getElementById('controlEffectiveness');
                if (ce) decisions.controlEffectiveness = ce.value;

                if (selected.length !== 5) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('controls_warning'), 'warning'
                    );
                    return false;
                }
            } else if (phase === 3) {
                var rt = document.getElementById('revenueTest');
                if (rt) decisions.revenueTest = rt.value;
                var invt = document.getElementById('inventoryTest');
                if (invt) decisions.inventoryTest = invt.value;
                var rect = document.getElementById('receivablesTest');
                if (rect) decisions.receivablesTest = rect.value;
                var ss = document.getElementById('sampleSize');
                if (ss) decisions.sampleSize = ss.value;
            } else if (phase === 4) {
                var flags = [];
                for (var j = 1; j <= 13; j++) {
                    var rfcb = document.getElementById('rf' + j);
                    if (rfcb && rfcb.checked) flags.push('rf' + j);
                }
                decisions.identifiedFlags = flags;
                var ao = document.getElementById('auditOpinion');
                if (ao) decisions.auditOpinion = ao.value;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var phase = state.currentPeriod;
            var phaseScore = 0;
            var maxPhaseScore = 25;
            var details = {};

            if (phase === 1) {
                var mat = d.materiality || 150000;
                if (mat >= 100000 && mat <= 200000) phaseScore += 5;
                else if (mat >= 50000 && mat <= 300000) phaseScore += 3;
                else phaseScore += 1;

                var riskHigh = {low: 0, medium: 3, high: 5};
                phaseScore += (riskHigh[d.riskRevenue] || 0);
                phaseScore += (riskHigh[d.riskInventory] || 0);
                phaseScore += (riskHigh[d.riskReceivables] || 0);

                var ctrlMap = {low: 1, medium: 5, high: 3};
                phaseScore += (ctrlMap[d.controlRisk] || 0);

                state.domainState.materialitySet = mat;
                state.domainState.riskProfile = d.riskRevenue + ' / ' + d.riskInventory + ' / ' + d.riskReceivables;
                details = {materiality: '$' + mat.toLocaleString(), riskRevenue: d.riskRevenue, riskInventory: d.riskInventory, riskReceivables: d.riskReceivables, controlRisk: d.controlRisk};

            } else if (phase === 2) {
                var optimalCtrls = ['ctrl1', 'ctrl2', 'ctrl3', 'ctrl4', 'ctrl5'];
                var sel = d.selectedControls || [];
                var correct = 0;
                for (var i = 0; i < sel.length; i++) {
                    if (optimalCtrls.indexOf(sel[i]) !== -1) correct++;
                }
                phaseScore += correct * 4;

                var effMap = {effective: 0, partially_effective: 5, ineffective: 2};
                phaseScore += (effMap[d.controlEffectiveness] || 0);

                details = {controlsCorrect: correct + ' of 5', effectiveness: d.controlEffectiveness};

            } else if (phase === 3) {
                var revMap = {cutoff_testing: 7, vouching: 5, confirmation: 3, analytical: 2};
                phaseScore += (revMap[d.revenueTest] || 0);

                var invMap = {observation: 7, test_counts: 4, price_testing: 3, analytical: 2};
                phaseScore += (invMap[d.inventoryTest] || 0);

                var recMap = {confirmation: 7, aging_analysis: 4, subsequent_receipts: 3, analytical: 2};
                phaseScore += (recMap[d.receivablesTest] || 0);

                var sizeMap = {small: 1, medium: 2, large: 4};
                phaseScore += (sizeMap[d.sampleSize] || 0);

                details = {revenueTest: d.revenueTest, inventoryTest: d.inventoryTest, receivablesTest: d.receivablesTest, sampleSize: d.sampleSize};

            } else if (phase === 4) {
                var realFlags = ['rf1','rf2','rf3','rf4','rf5','rf6','rf7','rf8','rf9','rf10'];
                var distractorFlags = ['rf11','rf12','rf13'];
                var userFlags = d.identifiedFlags || [];
                var found = 0, falsePos = 0;
                for (var k = 0; k < userFlags.length; k++) {
                    if (realFlags.indexOf(userFlags[k]) !== -1) found++;
                    else if (distractorFlags.indexOf(userFlags[k]) !== -1) falsePos++;
                }
                // Reward genuine red flags; penalise false positives so 'select all' is not optimal.
                var flagScore = Math.max(0, (found * 2) - (falsePos * 2));
                phaseScore += flagScore;

                var opMap = {unqualified: 0, qualified: 5, adverse: 2, disclaimer: 1};
                phaseScore += (opMap[d.auditOpinion] || 0);

                state.domainState.redFlagsFound = found;
                state.domainState.falsePositives = falsePos;
                details = {flagsFound: found + ' of 10', falsePositives: falsePos, opinion: d.auditOpinion};
            }

            phaseScore = Math.min(phaseScore, maxPhaseScore);
            state.domainState.totalScore += phaseScore;
            state.domainState.phaseScores.push(phaseScore);
            state.domainState.phaseLabels.push('P' + phase);

            var avg = state.domainState.totalScore / phase;
            if (avg >= 20) state.domainState.auditQuality = 'Excellent';
            else if (avg >= 15) state.domainState.auditQuality = 'Good';
            else if (avg >= 10) state.domainState.auditQuality = 'Adequate';
            else state.domainState.auditQuality = 'Needs Improvement';

            if (phase < 4) {
                state.domainState.currentPhaseName = this.PHASE_NAMES_EN[phase];
            }

            var self = this;
            setTimeout(function() {
                self._updateBriefing({currentPeriod: state.currentPeriod + 1});
            }, 500);

            return {
                period: phase,
                phaseScore: phaseScore,
                maxPhaseScore: maxPhaseScore,
                totalScore: state.domainState.totalScore,
                auditQuality: state.domainState.auditQuality
            };
        }

        _updateBriefing(state) {
            var phase = Math.min((state.currentPeriod || 1), 4);
            for (var i = 1; i <= 4; i++) {
                var panel = document.getElementById('phase' + i + 'Panel');
                if (panel) panel.style.display = (i === phase) ? 'block' : 'none';
            }
            var nameEl = document.getElementById('phaseNameDisplay');
            if (nameEl && phase >= 1 && phase <= 4) {
                var tfn = (window.mySimulation && typeof window.mySimulation.t === 'function')
                    ? window.mySimulation.t('phase_name_' + phase) : '';
                nameEl.textContent = (tfn && tfn.indexOf('phase_name_') === -1)
                    ? tfn : this.PHASE_NAMES_EN[phase - 1];
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore');
            uiManager.bind('flagsDisplay', 'domainState.redFlagsFound');
            uiManager.bind('qualityDisplay', 'domainState.auditQuality');
        }

        getChartConfig() {
            return {
                auditScoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Phase Score (max 25)',
                            data: [],
                            backgroundColor: [
                                'rgba(49,130,206,0.7)',
                                'rgba(56,161,105,0.7)',
                                'rgba(128,90,213,0.7)',
                                'rgba(229,62,62,0.7)'
                            ],
                            borderColor: [
                                '#3182ce',
                                '#38a169',
                                '#805ad5',
                                '#e53e3e'
                            ],
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: {display: true, text: 'Audit Score by Phase', font: {size: 14}}
                        },
                        scales: {
                            y: {beginAtZero: true, max: 25, title: {display: true, text: 'Score'}}
                        }
                    }
                }
            };
        }

        getChartData(state) {
            return {
                auditScoreChart: {
                    labels: state.domainState.phaseLabels,
                    datasets: [{data: state.domainState.phaseScores}]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var total = 0;
            for (var i = 0; i < history.length; i++) {
                total += (history[i].results && history[i].results.phaseScore ? history[i].results.phaseScore : 0);
            }
            var maxScore = 100;
            var pct = Math.round((total / maxScore) * 100);
            var performance = 'Needs Improvement';
            if (pct >= 85) performance = 'Excellent';
            else if (pct >= 70) performance = 'Good';
            else if (pct >= 55) performance = 'Adequate';

            var insights = [];
            if (pct >= 85) {
                insights.push('Outstanding audit performance with thorough risk assessment and effective testing strategy.');
            } else if (pct >= 70) {
                insights.push('Good audit quality. Consider refining substantive procedures to better target high-risk areas.');
            } else if (pct >= 55) {
                insights.push('Adequate performance. Review how inherent risk drives test selection and sample sizing.');
            } else {
                insights.push('Further study recommended. Focus on linking risk assessment to audit procedures and evidence evaluation.');
            }

            return {
                totalScore: total,
                maxScore: maxScore,
                percentage: pct,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var phase = results.period || state.currentPeriod;
            if (results.phaseScore < 12) {
                if (phase === 1) return window.mySimulation.t('hint_risk');
                if (phase === 2) return window.mySimulation.t('hint_controls');
                if (phase === 3) return window.mySimulation.t('hint_substantive');
                if (phase === 4) return window.mySimulation.t('hint_findings');
            }
            if (results.phaseScore >= 20) return window.mySimulation.t('hint_excellent');
            return null;
        }

        getHistoryTableConfig() {
            return [
                {key: 'results.period', label: 'Phase', i18nKey: 'col_phase'},
                {key: 'results.phaseScore', label: 'Score', i18nKey: 'col_phase_score', formatter: (v) => v + ' / 25'},
                {key: 'results.totalScore', label: 'Cumulative', i18nKey: 'col_total_score'},
                {key: 'results.auditQuality', label: 'Quality', i18nKey: 'col_quality'}
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:                `AuditTrail: Audit Risk Assessment Lab`,
                    subtitle:             `Plan and execute an audit of Precision Manufacturing Co.`,
                    phase_label:          `Phase`,
                    period_of:            `of`,
                    score_label:          `Audit Score`,
                    flags_label:          `Red Flags Found`,
                    phase_name_label:     `Current Phase`,
                    quality_label:        `Audit Quality`,
                    company_heading:      `Client Profile — Precision Manufacturing Co.`,
                    co_industry:          `Industry`,
                    co_industry_val:      `Industrial Manufacturing`,
                    co_revenue:           `Revenue`,
                    co_rev_prior:         `(Prior: $51.2M, +22%)`,
                    co_net_income:        `Net Income`,
                    co_total_assets:      `Total Assets`,
                    co_inventory:         `Inventory`,
                    co_inv_prior:         `(Prior: $8.7M, +41%)`,
                    co_receivables:       `Accounts Receivable`,
                    co_rec_prior:         `(Prior: $6.8M, +41%)`,
                    co_debt:              `Long-Term Debt`,
                    co_debt_cov:          `(Covenant: D/E < 2.5, Current: 2.3)`,
                    co_concentration:     `Customer Concentration`,
                    co_conc_val:          `Top customer = 34% of revenue`,
                    co_related:           `Related Parties`,
                    co_related_val:       `CEO holds 15% of key supplier`,
                    co_dso:               `Days Sales Outstanding`,
                    co_dso_val:           `58 days (Prior: 42 days, Industry: 40)`,
                    phase1_heading:       `Phase 1: Risk Assessment and Planning`,
                    phase1_desc:          `Review the client profile. Set overall materiality and assess inherent risk for key accounts and control risk.`,
                    materiality_label:    `Overall Materiality ($)`,
                    materiality_ph:       `Enter amount between $50,000 and $500,000`,
                    materiality_hint:     `Typical range: 3-5% of pre-tax income or 0.5-1% of revenue`,
                    risk_revenue_label:   `Inherent Risk — Revenue`,
                    risk_inventory_label: `Inherent Risk — Inventory`,
                    risk_receivables_label: `Inherent Risk — Receivables`,
                    control_risk_label:   `Control Risk (Overall)`,
                    risk_low:             `Low`,
                    risk_medium:          `Medium`,
                    risk_high:            `High`,
                    phase2_heading:       `Phase 2: Internal Controls Testing`,
                    phase2_desc:          `Select exactly 5 controls to test. Then assess overall control effectiveness.`,
                    ctrl1_label:          `Segregation of duties in accounts payable`,
                    ctrl2_label:          `Authorization controls for purchases over $10,000`,
                    ctrl3_label:          `Monthly bank reconciliations`,
                    ctrl4_label:          `Physical inventory access restrictions`,
                    ctrl5_label:          `IT general controls and access management`,
                    ctrl6_label:          `Automated three-way matching for payables`,
                    ctrl7_label:          `Management review of manual journal entries`,
                    ctrl8_label:          `Customer credit approval process`,
                    effectiveness_label:  `Overall Control Effectiveness Assessment`,
                    eff_effective:        `Effective`,
                    eff_partial:          `Partially Effective`,
                    eff_ineffective:      `Ineffective`,
                    phase3_heading:       `Phase 3: Substantive Testing`,
                    phase3_desc:          `Design substantive test procedures for three high-risk accounts and set your sample size.`,
                    revenue_test_label:   `Revenue — Primary Test Procedure`,
                    rev_vouching:         `Vouching to source documents`,
                    rev_confirmation:     `Customer confirmation`,
                    rev_analytical:       `Analytical procedures`,
                    rev_cutoff:           `Cutoff testing around year-end`,
                    inventory_test_label: `Inventory — Primary Test Procedure`,
                    inv_observation:      `Physical observation and counting`,
                    inv_test_counts:      `Test counts and roll-forward`,
                    inv_analytical:       `Analytical procedures`,
                    inv_price:            `Price testing and NRV analysis`,
                    receivables_test_label: `Receivables — Primary Test Procedure`,
                    rec_confirmation:     `External confirmation`,
                    rec_aging:            `Aging analysis review`,
                    rec_subsequent:       `Subsequent receipts testing`,
                    rec_analytical:       `Analytical procedures`,
                    sample_size_label:    `Sample Size Strategy`,
                    size_small:           `Small — Focus on key items only`,
                    size_medium:          `Medium — Representative sample`,
                    size_large:           `Large — Extensive coverage`,
                    phase4_heading:       `Phase 4: Findings and Audit Opinion`,
                    phase4_desc:          `Review all evidence and select the red flags you identified. Then form your audit opinion.`,
                    flags_heading:        `Identified Red Flags`,
                    rf1_label:            `Revenue recognized before goods shipped (cutoff issue)`,
